/* Campus requests are local demonstrations. Nothing is sent to another person. */
(()=>{
 const KEY='dormmart-wanted-v1', view=$('#wanted-view');
 const today=()=>localDate();
 const future=n=>{const d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
 const seeds=[
  {id:'demo-projector',title:'Projector for movie night',category:'Electronics',mode:'rent',budget:300,date:future(5),area:'Student centre',note:'A projector with an HDMI connection for an evening screening. Happy to collect and return the next morning.',owner:'Tara',status:'open',mine:false,offers:[]},
  {id:'demo-tools',title:'A toolkit for moving day',category:'Home & living',mode:'share',budget:0,date:future(8),area:'North campus gate',note:'Looking for a screwdriver set and a small hammer to assemble a shelf. Just for an afternoon.',owner:'Rohan',status:'open',mine:false,offers:[]},
  {id:'demo-calculator',title:'Scientific calculator',category:'Electronics',mode:'buy',budget:650,date:future(12),area:'Library entrance',note:'A working non-programmable calculator for class. Please mention the model and condition.',owner:'Meera',status:'open',mine:false,offers:[]}
 ];
 let posts;
 try{const raw=JSON.parse(localStorage.getItem(KEY));posts=Array.isArray(raw)?raw.filter(p=>p&&typeof p.id==='string'&&typeof p.title==='string'&&typeof p.note==='string'&&['rent','buy','share'].includes(p.mode)&&['open','fulfilled'].includes(p.status)&&Array.isArray(p.offers)).map(p=>({...p,mine:p.mine===true,offers:p.offers.filter(o=>o&&typeof o.title==='string'&&typeof o.note==='string')})):seeds}catch{posts=seeds}
 let filter='all',query='';
 const modes={rent:'Rent',buy:'Buy',share:'Borrow free'};
 function save(next){try{localStorage.setItem(KEY,JSON.stringify(next));posts=next;return true}catch{toast('Could not save this request. Your changes were not applied. Free some browser storage and try again.');return false}}
 function card(p){const expired=p.date&&p.date<today();return `<article class="wanted-card ${p.mine?'is-mine':''}"><div class="wanted-card-top"><span class="badge-chip">${escapeHTML(modes[p.mode])}</span><span class="request-state">${p.status==='fulfilled'?'✓ Found it':expired?'Date passed':'Looking for'}</span></div><p class="eyebrow">${escapeHTML(p.category||'Other')}</p><h2>${escapeHTML(p.title)}</h2><p class="wanted-note">${escapeHTML(p.note)}</p><dl><div><dt>Budget${p.mode==='rent'?' / day':''}</dt><dd>${p.mode==='share'?'Free borrowing':Number(p.budget)>0?money(p.budget):'Flexible'}</dd></div><div><dt>Needed by</dt><dd>${escapeHTML(p.date||'Flexible')}</dd></div></dl><p class="micro">◎ ${escapeHTML(p.area||'Campus pickup')} · ${p.mine?'You':escapeHTML(p.owner)}${p.mine?'':' · Demo request'}</p>${p.offers.length?`<details class="request-offers"><summary>${p.offers.length} saved demo offer${p.offers.length===1?'':'s'}</summary>${p.offers.map(o=>`<p><strong>${escapeHTML(o.title)}</strong><br>${escapeHTML(o.note)}${LISTINGS.some(x=>x.id===o.itemId)?`<br><a href="#item-${Number(o.itemId)}">View offered listing ↗</a>`:''}</p>`).join('')}</details>`:''}<div class="wanted-actions">${p.mine?`<button class="button small" data-wanted-status="${escapeHTML(p.id)}">${p.status==='open'?'Mark as found':'Reopen request'}</button><button class="text-btn" data-wanted-edit="${escapeHTML(p.id)}">Edit</button><button class="text-btn" data-wanted-delete="${escapeHTML(p.id)}">Delete</button>`:`<button class="button small" data-wanted-offer="${escapeHTML(p.id)}" ${p.status!=='open'||expired?'disabled':''}>${p.offers.length?'Update my offer':'I have something ↗'}</button>`}</div></article>`}
 function render(){
  const shown=posts.filter(p=>(filter!=='mine'||p.mine)&&(filter!=='open'||p.status==='open'&&(!p.date||p.date>=today()))&&(p.title+' '+p.note+' '+p.category).toLowerCase().includes(query.toLowerCase()));
  view.innerHTML=`<div class="wanted-masthead"><div><p class="eyebrow">ASK LOCAL. FIND MORE.</p><h1>The campus<br><em>wishlist.</em><span aria-hidden="true">✳</span></h1><p>Can’t find the right thing? Put the word out.</p></div><div class="wanted-masthead-aside"><span class="wanted-number">${posts.filter(p=>p.status==='open'&&(!p.date||p.date>=today())).length.toString().padStart(2,'0')}</span><p>open requests on this browser</p><button class="button" id="new-wanted">+ Request an item</button></div></div><div class="board-notice"><strong>Demo noticeboard</strong><span>Requests and offers are saved only in this browser. Nothing is published or sent to another person.</span></div><div class="wanted-toolbar"><div role="group" aria-label="Request filters">${[['all','All requests'],['open','Open requests'],['mine','My requests']].map(([v,l])=>`<button class="chip ${filter===v?'active':''}" data-wanted-filter="${v}" aria-pressed="${filter===v}">${l}</button>`).join('')}</div><label class="wanted-search"><span class="sr-only">Search requests</span><input id="wanted-search" type="search" placeholder="Search the wishlist…" value="${escapeHTML(query)}"></label></div><div class="wanted-grid" aria-live="polite">${shown.length?shown.map(card).join(''):'<div class="community-empty"><h2>A little quiet here.</h2><p>Try another search, or be the first to ask for what you need.</p><button class="button" id="empty-wanted">Post a request ↗</button></div>'}</div>`;
  $('#new-wanted').onclick=openForm;$('#empty-wanted')?.addEventListener('click',openForm);
  $('#wanted-search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;render();$('#wanted-search').focus();if(pos!==null)try{$('#wanted-search').setSelectionRange(pos,pos)}catch{}};
 }
 function openForm(existing=null){
  if(!existing?.mine)existing=null;
  showModal(`<p class="eyebrow">PUT THE WORD OUT</p><h2 id="modal-title">What are you looking for?</h2><p class="micro">A local demo request. Use a public pickup area, not a private address.</p><form id="wanted-form" class="detail-form"><label>Item name<input name="title" maxlength="80" required placeholder="e.g. A projector for movie night"></label><div class="detail-grid"><label>I’d like to<select name="mode" id="wanted-mode"><option value="rent">Rent it</option><option value="buy">Buy it</option><option value="share">Borrow for free</option></select></label><label>Category<select name="category">${[...new Set(LISTINGS.map(x=>x.category)),'Other'].map(c=>`<option>${escapeHTML(c)}</option>`).join('')}</select></label></div><div class="detail-grid"><label id="wanted-budget-label">Maximum budget per day (₹)<input name="budget" type="number" min="0" max="1000000" step="1" placeholder="Leave blank for flexible"></label><label>Needed by<input name="date" type="date" min="${today()}"></label></div><label>Campus pickup area<input name="area" maxlength="100" required placeholder="e.g. Library entrance"></label><label>What should the owner know?<textarea name="note" maxlength="600" required rows="3" placeholder="Preferred condition, how long you need it, and any essentials"></textarea></label><p id="wanted-error" class="form-error" role="alert"></p><button class="button" type="submit">Post demo request ↗</button></form>`);
  $('#wanted-mode').onchange=e=>{const label=$('#wanted-budget-label'),input=label.querySelector('input');label.firstChild.textContent=e.target.value==='rent'?'Maximum budget per day (₹)':'Maximum total budget (₹)';label.hidden=e.target.value==='share';input.disabled=e.target.value==='share'};
  if(existing){for(const key of ['title','mode','category','budget','date','area','note'])$('#wanted-form').elements[key].value=existing[key]||'';$('#wanted-mode').dispatchEvent(new Event('change'));$('#wanted-form button[type=submit]').textContent='Save request changes';}
  $('#wanted-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),title=String(f.get('title')).trim(),note=String(f.get('note')).trim(),area=String(f.get('area')).trim(),date=String(f.get('date')||'');if(!title||!note||!area||date&&(!validDate(date)||date<today())){$('#wanted-error').textContent='Add the item, pickup area and details, and choose today or a future date.';return}
   const post={id:existing?.id||crypto.randomUUID(),title,note,area,date,mode:f.get('mode'),category:f.get('category'),budget:Number(f.get('budget')||0),owner:profile.name||'You',mine:true,status:existing?.status||'open',offers:existing?.offers||[]};
   if(save(existing?posts.map(x=>x.id===existing.id?post:x):[post,...posts])){filter='mine';query='';closeModal();location.hash='wanted';render();toast('Request saved on this browser.')}};
 }
 function offer(p){
  const own=userListings.filter(x=>!listingUnavailable(x));
  showModal(`<p class="eyebrow">HELP A NEIGHBOUR OUT</p><h2 id="modal-title">Offer an item</h2><p>For: <strong>${escapeHTML(p.title)}</strong></p><p class="micro">This saves a demo offer locally; it does not send a message. Confirm availability and dates before a real exchange.</p>${own.length?`<form id="wanted-offer-form" class="detail-form"><label>Choose one of your listings<select name="item">${own.map(x=>`<option value="${x.id}">${escapeHTML(x.title)} · ${modes[x.mode]}</option>`).join('')}</select></label><label>Details for the requester<textarea name="note" required maxlength="400" rows="3" placeholder="Condition, dates and your proposed price">${escapeHTML(p.offers[0]?.note||'')}</textarea></label><button class="button" type="submit">Save demo offer</button></form>`:'<p>Add an available listing first so the requester can see its photos, price and condition.</p><button class="button" id="offer-add-listing">+ List an item</button>'}`);
  $('#offer-add-listing')?.addEventListener('click',openListingForm);
  $('#wanted-offer-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),item=own.find(x=>x.id===Number(f.get('item'))),note=String(f.get('note')).trim();if(!item||!note)return;const next=posts.map(x=>x.id===p.id?{...x,offers:[{itemId:item.id,title:item.title,note}]}:x);if(save(next)){closeModal();render();toast('Demo offer saved locally. No message was sent.')}});
 }
 view.addEventListener('click',e=>{
  const edit=e.target.closest('[data-wanted-edit]');if(edit){const p=posts.find(x=>x.id===edit.dataset.wantedEdit&&x.mine);if(p)openForm(p);return}
  const f=e.target.closest('[data-wanted-filter]');if(f){filter=f.dataset.wantedFilter;render();view.querySelector(`[data-wanted-filter="${filter}"]`).focus();return}
  const s=e.target.closest('[data-wanted-status]');if(s){const p=posts.find(x=>x.id===s.dataset.wantedStatus&&x.mine);if(p&&save(posts.map(x=>x===p?{...x,status:x.status==='open'?'fulfilled':'open'}:x)))render();return}
  const o=e.target.closest('[data-wanted-offer]');if(o){const p=posts.find(x=>x.id===o.dataset.wantedOffer&&!x.mine&&x.status==='open');if(p&&(!p.date||p.date>=today()))offer(p);return}
  const d=e.target.closest('[data-wanted-delete]');if(d){const p=posts.find(x=>x.id===d.dataset.wantedDelete&&x.mine);if(!p)return;showModal(`<h2 id="modal-title">Delete this request?</h2><p>${escapeHTML(p.title)} will be removed from this browser.</p><button class="button" id="cancel-wanted-delete">Keep request</button> <button class="text-btn" id="confirm-wanted-delete">Delete request</button>`);$('#cancel-wanted-delete').onclick=closeModal;$('#confirm-wanted-delete').onclick=()=>{if(save(posts.filter(x=>x.id!==p.id))){closeModal();render();toast('Request deleted.')}}}
 });
 window.renderWantedRoute=hash=>{view.hidden=hash!=='#wanted';if(hash!=='#wanted')return false;lastPage='wanted';['home','explore','profile','messages','item'].forEach(x=>$('#'+x+'-view').hidden=true);if($('#modal').open)closeModal();document.querySelectorAll('.header nav a,.mobile-dock a').forEach(a=>a.hash==='#wanted'?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current'));$('#account-button').removeAttribute('aria-current');document.title='Campus wishlist — DormMart';render();window.scrollTo(0,0);return true};
 const results=$('#results');function emptyLink(){if(!results.querySelector('.card')&&!results.querySelector('.empty-wanted-link')){const a=document.createElement('a');a.href='#wanted';a.className='button empty-wanted-link';a.textContent='Can’t find it? Request an item ↗';results.append(a)}}
 new MutationObserver(emptyLink).observe(results,{childList:true});emptyLink();route();
})();
